#!/bin/bash
# ======================================================================
# This file was automatically generated by SbatchMan.
# Do not edit this file manually (unless you know what you are doing).
# ======================================================================

# Local execution script

# Global SbatchMan env variables
export SBATCHMAN_WD={CWD}
export SBATCHMAN_JOB_DIR={EXP_DIR}
export SBATCHMAN_JOB_TAG={JOB_TAG}
export SBATCHMAN_JOB_CONFIG={CONFIG}

echo "start_timestamp: '$(date +%Y%m%d_%H%M%S.%N)'" >> "{EXP_DIR}/metadata.yaml"


# Change to the submission directory
cd "{CWD}"

# Update job_id in metadata.yaml
perl -i -pe"s/job_id: [0-9]*/job_id: $$/" "{EXP_DIR}/metadata.yaml"

# Update status to RUNNING
perl -i -pe's/status: .*/status: RUNNING/' {EXP_DIR}/metadata.yaml

# (Optional) Preprocess command
{PREPROCESS}

# User command
{CMD}
CMD_EXIT_CODE=$?

# Default final exit code/status from CMD
EXIT_CODE=$CMD_EXIT_CODE
STATUS="COMPLETED"
if [ $CMD_EXIT_CODE -ne 0 ]; then
  STATUS="FAILED"
fi

# (Optional) Postprocess command
{POSTPROCESS}

# (Optional) Check command (overrides only on failure)
if [ -n "{CHECK}" ]; then
  {CHECK}
  CHECK_EXIT_CODE=$?
  if [ $CHECK_EXIT_CODE -ne 0 ]; then
    EXIT_CODE=$CHECK_EXIT_CODE
    STATUS="CHECK_FAIL"
  fi
fi

# Update metadata
perl -i -pe"s/status: .*/status: $STATUS/" {EXP_DIR}/metadata.yaml
perl -i -pe"s/exitcode: .*/exitcode: $EXIT_CODE/" {EXP_DIR}/metadata.yaml

echo "end_timestamp: '$(date +%Y%m%d_%H%M%S.%N)'" >> "{EXP_DIR}/metadata.yaml"


exit $EXIT_CODE